import argparse
import os
import sys
from datetime import date, timedelta
from pathlib import Path
from statistics import mean, median

from dotenv import load_dotenv
from garmin_personal_api import GarminPersonalApiClient, PersonalApiAuthenticator


def main() -> int:
    """Fetch and print Garmin HRV summaries for a recent date range."""
    parser = argparse.ArgumentParser(description="Fetch your Garmin HRV summaries.")
    parser.add_argument(
        "--days",
        type=int,
        default=30,
        help="number of calendar days to fetch (default: 30)",
    )
    args = parser.parse_args()
    if args.days < 1:
        parser.error("--days must be at least 1")

    load_dotenv(Path(__file__).resolve().with_name(".env"))
    api_key = os.getenv("GARMIN_PERSONAL_API_KEY") or os.getenv("GARMIN_API_KEY")
    if not api_key:
        print(
            "Set GARMIN_PERSONAL_API_KEY in .env (or in your environment).",
            file=sys.stderr,
        )
        return 1

    end_date = date.today()
    start_date = end_date - timedelta(days=args.days - 1)

    try:
        with PersonalApiAuthenticator() as authenticator:
            token = authenticator.obtain_token(api_key)
        with GarminPersonalApiClient(token.access_token) as client:
            summaries = client.get_daily_hrv_summaries(start_date, end_date)
    except Exception as error:
        print(f"Could not fetch Garmin HRV data: {error}", file=sys.stderr)
        return 1

    print(format_report(summaries, start_date, end_date))
    return 0


def extract_records(payload: object, inherited_date: object = None) -> list[dict[str, object]]:
    """Find HRV summary records in Garmin's list or nested-object responses."""
    metric_fields = ("lastNightAvg", "weeklyAvg")
    if isinstance(payload, list):
        records = []
        for item in payload:
            records.extend(extract_records(item, inherited_date))
        return records
    if not isinstance(payload, dict):
        return []

    record_date = payload.get("calendarDate") or payload.get("date") or inherited_date
    if any(_number(payload.get(field)) is not None for field in metric_fields):
        record = dict(payload)
        if record_date is not None and "calendarDate" not in record and "date" not in record:
            record["calendarDate"] = record_date
        return [record]

    records = []
    for value in payload.values():
        records.extend(extract_records(value, record_date))
    return records


def _number(value: object) -> int | float | None:
    """Return numeric HRV data while excluding booleans and other JSON types."""
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return value
    return None


def format_report(payload: object, start_date: date, end_date: date) -> str:
    """Format HRV readings as a personal, descriptive trend report."""
    records = extract_records(payload)
    metric_fields = ("lastNightAvg", "weeklyAvg")
    metric_field = max(
        metric_fields,
        key=lambda field: sum(_number(record.get(field)) is not None for record in records),
    )
    readings = [
        (
            str(record.get("calendarDate") or record.get("date") or "Date unavailable"),
            _number(record.get(metric_field)),
        )
        for record in records
    ]
    readings = [(day, value) for day, value in readings if value is not None]
    readings.sort(key=lambda reading: reading[0])

    title = f"Garmin HRV report: {start_date} to {end_date}"
    if not readings:
        return f"{title}\nNo lastNightAvg or weeklyAvg readings were returned."

    values = [value for _, value in readings]
    lines = [
        title,
        f"Metric: {metric_field} (ms)",
        f"Readings: {len(values)}",
        f"Latest: {values[-1]:.1f} ms on {readings[-1][0]}",
        f"Period median: {median(values):.1f} ms",
        f"Period range: {min(values):.1f}-{max(values):.1f} ms",
    ]

    recent = values[-7:]
    lines.append(f"Latest {len(recent)} readings average: {mean(recent):.1f} ms")
    if len(values) >= 14:
        previous = values[-14:-7]
        previous_average = mean(previous)
        recent_average = mean(recent)
        change = (recent_average - previous_average) / previous_average * 100
        lines.append(f"Previous 7 readings average: {previous_average:.1f} ms")
        lines.append(f"Change between those periods: {change:+.1f}%")

    lines.append("Descriptive only; HRV varies and is not a diagnosis or readiness verdict.")
    return "\n".join(lines)


if __name__ == "__main__":
    raise SystemExit(main())